export function fmtPct(n: number, digits = 1): string {
  return `${n.toFixed(digits)}%`;
}

export function fmtPp(n: number, digits = 2): string {
  const sign = n > 0 ? "+" : "";
  return `${sign}${n.toFixed(digits)} pp`;
}

export function fmtDwellings(n: number | null): string {
  if (n == null) return "???";
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(2)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(0)}k`;
  return String(n);
}

export function materialCountries(minShare = 10): CountryStockRow[] {
  return COUNTRY_STOCK.filter((c) => c.sharePct >= minShare);
}

export function shrinkingTrends(): TrendRow[] {
  return TRENDS.filter((t) => t.deltaPp != null && t.deltaPp < 0).sort(
    (a, b) => (a.deltaPp ?? 0) - (b.deltaPp ?? 0),
  );
}

export function growingTrends(): TrendRow[] {
  return TRENDS.filter((t) => t.deltaPp != null && t.deltaPp > 0).sort(
    (a, b) => (b.deltaPp ?? 0) - (a.deltaPp ?? 0),
  );
}

