/**
 * Social housing stock share in OECD (2026).
 *
 * Core question: Which OECD countries still have a material social-rental
 * stock, and how fast is that share shrinking?
 *
 * Perimeter: OECD Affordable Housing Database indicator PH4.2 ??? social rental
 * dwellings as % of total housing stock (QuASH 2023 / earlier rounds). Latest
 * observation is typically 2018???2022; UK figures are England. Definitions of
 * "social rental" differ by country (see SOURCE_NOTE).
 *
 * Headline: Social rental dwellings are ~7% of OECD housing stock on average;
 * only three countries still clear 20%, and most large stocks are slowly
 * losing share even when absolute unit counts rise.
 */

export type Confidence = "disclosed" | "estimated" | "carried";

export type SizeBand = "large" | "moderate" | "small" | "minimal";

export type Region =
  | "Northern Europe"
  | "Western Europe"
  | "Southern Europe"
  | "Central & Eastern Europe"
  | "North America"
  | "Asia-Pacific"
  | "Latin America"
  | "OECD / EU";

export const SOURCE_NOTE =
  "OECD Affordable Housing Database, indicator PH4.2 Social rental housing stock (OECD QuASH 2023, 2021, 2019, 2016 and national supplements). Values are social rental dwellings as a share of total dwellings for 2022 or the latest available year. Country definitions of social rental housing are not fully harmonised: Netherlands estimates include below-market private rentals; Austria is main residences only; US includes public housing, Sections 202/811, and LIHTC income-restricted units (preliminary); Canada excludes Qu??bec SHQ units; New Zealand is central-government funded places only; Norway is municipal dwellings (~75% of social stock). Trend comparisons use OECD???s paired ~2010 vs ~2022 observations where both exist. Absolute dwelling counts from Table PH4.2.A1. Cite: OECD (2024), https://oe.cd/ahd.";

export const SOURCES = [
  {
    label: "OECD Affordable Housing Database ??? PH4.2",
    url: "https://www.oecd.org/en/data/datasets/oecd-affordable-housing-database.html",
  },
  {
    label: "PH4.2 Social rental housing stock (PDF)",
    url: "https://webfs.oecd.org/Els-com/Affordable_Housing_Database/PH4-2-Social-rental-housing-stock.pdf",
  },
  {
    label: "PH4.2 underlying workbook (XLSX)",
    url: "https://webfs.oecd.org/Els-com/Affordable_Housing_Database/PH4-2-Social-rental-housing-stock.xlsx",
  },
] as const;

export const HEADLINE = {
  oecdAvgSharePct: 7.07,
  euAvgSharePct: 7.99,
  socialDwellingsMillionApprox: 28,
  countriesAbove20: 3,
  countriesAbove10: 8,
  countriesShrinkingShare: 16,
  countriesGrowingShare: 5,
  largestSharePct: 34.07,
  largestShareCountry: "Netherlands",
  steepestDropPp: -3.44,
  steepestDropCountry: "Poland",
  confidence: "disclosed" as Confidence,
};

export type CountryStockRow = {
  id: string;
  country: string;
  region: Region;
  sharePct: number;
  year: number | null;
  dwellings: number | null;
  sizeBand: SizeBand;
  confidence: Confidence;
};

