/**
 * QA: social-housing-stock-share-in-oecd-2026
 * // viz-types: ranked bars, slope/dumbbell deltas, provider stacked bars, share??units scatter | layout: default
 * // smoke-marker: Social rental % of dwellings
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";
import { startStaticServer, stopStaticServer } from "./lib/static-server.mjs";
import { auditVizInteractions } from "./lib/viz-interaction-qa.mjs";
import {
  COUNTRY_STOCK,
  HEADLINE,
  PROVIDER_MIX,
  TRENDS,
} from "../src/data/social-housing-stock-share-in-oecd-2026-data.ts";

assert.ok(HEADLINE.oecdAvgSharePct >= 7.0 && HEADLINE.oecdAvgSharePct <= 7.2);
assert.ok(HEADLINE.largestSharePct >= 34 && HEADLINE.largestSharePct <= 35);
assert.equal(HEADLINE.largestShareCountry, "Netherlands");
assert.equal(HEADLINE.countriesAbove20, 3);
assert.equal(HEADLINE.countriesAbove10, 8);
assert.ok(COUNTRY_STOCK.length >= 25);
assert.ok(TRENDS.length >= 15);
assert.ok(PROVIDER_MIX.length >= 8);
const nl = COUNTRY_STOCK.find((r) => r.id === "nld");
assert.ok(nl && nl.sharePct >= 34);

const root = process.cwd();
const slug = "social-housing-stock-share-in-oecd-2026";
const markers = [
  "Social rental % of dwellings",
  "Social rental stock: who still has scale",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(200);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4182);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    await page.goto(`http://127.0.0.1:${port}/blog/${slug}.html`, {
      waitUntil: "domcontentloaded",
      timeout: 45000,
    });
    await page.waitForSelector(`[data-viz="${slug}"]`, { timeout: 20000 });
    for (const m of markers) {
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "Share change");
    await clickBtn(page, "Providers");
    await clickBtn(page, "Share ?? units");
    await clickBtn(page, "Share ranking");
    await clickBtn(page, "???20%");
    await clickBtn(page, "All");
    await clickBtn(page, "Western Europe");
    await auditVizInteractions(page, { slug, maxButtons: 14 });
    console.log("??? QA passed:", slug);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error("??? QA failed:", err);
  process.exit(1);
});

