"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AGGREGATES,
  COUNTRY_STOCK,
  HEADLINE,
  PROVIDER_MIX,
  REGIONS,
  SIZE_BAND_LABELS,
  SOURCE_NOTE,
  TRENDS,
  fmtDwellings,
  fmtPct,
  fmtPp,
  type Region,
  type SizeBand,
} from "@/data/social-housing-stock-share-in-oecd-2026-data";

// viz-types: ranked bars, slope/dumbbell deltas, provider stacked bars, share??units scatter | layout: default

type PanelId = "rank" | "change" | "providers" | "scatter";
type BandFilter = "all" | SizeBand;
type RegionFilter = "all" | Region;
type SortMode = "share-desc" | "delta-asc" | "dwellings-desc";

const NAVY = "#0f172a";
const TEAL = "#0f766e";
const AMBER = "#d97706";
const ROSE = "#be123c";
const SLATE = "#64748b";
const SKY = "#0284c7";
const LIME = "#65a30d";
const VIOLET = "#7c3aed";

const BAND_COLOR: Record<SizeBand, string> = {
  large: TEAL,
  moderate: SKY,
  small: AMBER,
  minimal: SLATE,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((opt) => {
          const active = opt.id === value;
          return (
            <button
              key={opt.id}
              type="button"
              onClick={() => onChange(opt.id)}
              className={`rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
                active
                  ? "bg-slate-900 text-white"
                  : "text-slate-600 hover:bg-slate-100"
              }`}
            >
              {opt.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export function SocialHousingStockShareInOecd2026Dashboard() {
  const [panel, setPanel] = useState<PanelId>("rank");
  const [band, setBand] = useState<BandFilter>("all");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [sort, setSort] = useState<SortMode>("share-desc");
  const [materialOnly, setMaterialOnly] = useState(false);

  const filteredStock = useMemo(() => {
    let rows = COUNTRY_STOCK.filter((r) => r.id !== "col" || !materialOnly);
    if (materialOnly) rows = rows.filter((r) => r.sharePct >= 10);
    if (band !== "all") rows = rows.filter((r) => r.sizeBand === band);
    if (region !== "all") rows = rows.filter((r) => r.region === region);
    return rows;
  }, [band, region, materialOnly]);

  const rankData = useMemo(() => {
    const rows = [...filteredStock];
    if (sort === "dwellings-desc") {
      rows.sort((a, b) => (b.dwellings ?? 0) - (a.dwellings ?? 0));
    } else {
      rows.sort((a, b) => b.sharePct - a.sharePct);
    }
    return rows.map((r) => ({
      ...r,
      short: r.country.replace("United Kingdom (England)", "UK (Eng.)"),
    }));
  }, [filteredStock, sort]);

  const changeData = useMemo(() => {
    let rows = TRENDS.filter((t) => t.deltaPp != null);
    if (materialOnly) rows = rows.filter((t) => (t.shareLatest ?? 0) >= 10);
    if (region !== "all") rows = rows.filter((t) => t.region === region);
    if (band !== "all") {
      rows = rows.filter((t) => {
        const stock = COUNTRY_STOCK.find((c) => c.id === t.id);
        return stock?.sizeBand === band;
      });
    }
    rows = [...rows].sort((a, b) =>
      sort === "delta-asc"
        ? (a.deltaPp ?? 0) - (b.deltaPp ?? 0)
        : (b.shareLatest ?? 0) - (a.shareLatest ?? 0),
    );
    return rows.map((t) => ({
      ...t,
      short: t.country.replace("United Kingdom (England)", "UK (Eng.)"),
      around2010: t.shareAround2010,
      latest: t.shareLatest,
      delta: t.deltaPp,
    }));
  }, [band, region, materialOnly, sort]);

  const providerData = useMemo(() => {
    let rows = [...PROVIDER_MIX];
    if (region !== "all") {
      const ids = new Set(
        COUNTRY_STOCK.filter((c) => c.region === region).map((c) => c.id),
      );
      rows = rows.filter((r) => ids.has(r.id));
    }
    if (materialOnly) {
      const ids = new Set(
        COUNTRY_STOCK.filter((c) => c.sharePct >= 10).map((c) => c.id),
      );
      rows = rows.filter((r) => ids.has(r.id));
    }
    return rows.map((r) => ({
      short: r.country.replace("United Kingdom (England)", "UK (Eng.)"),
      national: +(r.nationalPct * 100).toFixed(1),
      municipal: +(r.regionalMunicipalPct * 100).toFixed(1),
      nonprofit: +(r.nonprofitCoopPct * 100).toFixed(1),
      forProfit: +(r.forProfitPct * 100).toFixed(1),
      other: +(r.otherPct * 100).toFixed(1),
    }));
  }, [region, materialOnly]);

  const scatterData = useMemo(() => {
    return filteredStock
      .filter((r) => r.dwellings != null && r.dwellings > 0)
      .map((r) => ({
        ...r,
        x: r.sharePct,
        y: (r.dwellings ?? 0) / 1_000_000,
        z: Math.max(40, Math.sqrt(r.dwellings ?? 0) / 25),
        short: r.country.replace("United Kingdom (England)", "UK (Eng.)"),
      }));
  }, [filteredStock]);

  const shrinkCount = changeData.filter((d) => (d.delta ?? 0) < 0).length;
  const growCount = changeData.filter((d) => (d.delta ?? 0) > 0).length;

  return (
    <div className="space-y-6" data-viz="social-housing-stock-share-in-oecd-2026">
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-50 to-white p-5 sm:p-6">
        <p className="text-xs font-semibold uppercase tracking-wide text-teal-800">
          Social rental % of dwellings ?? OECD PH4.2
        </p>
        <h2 className="mt-1 text-xl font-bold text-slate-900 sm:text-2xl">
          Social rental stock: who still has scale, and who is losing share
        </h2>
        <p className="mt-2 max-w-3xl text-sm leading-relaxed text-slate-600">
          Across the OECD, social rental dwellings average{" "}
          <span className="font-semibold text-slate-900">
            {fmtPct(HEADLINE.oecdAvgSharePct)}
          </span>{" "}
          of the housing stock (~{HEADLINE.socialDwellingsMillionApprox}M units).
          Only {HEADLINE.countriesAbove20} countries still clear 20%;{" "}
          {HEADLINE.countriesAbove10} clear 10%. Most paired histories show share
          erosion even when absolute unit counts rise.
        </p>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
          <Stat label="OECD avg share" value={fmtPct(HEADLINE.oecdAvgSharePct)} />
          <Stat label="Largest share" value={`${HEADLINE.largestShareCountry} ${fmtPct(HEADLINE.largestSharePct)}`} />
          <Stat label="Steepest share drop" value={`${HEADLINE.steepestDropCountry} ${fmtPp(HEADLINE.steepestDropPp)}`} />
          <Stat label="Material (???10%)" value={`${HEADLINE.countriesAbove10} countries`} />
        </div>
      </div>

      <div className="flex flex-col gap-3 rounded-xl border border-slate-200 bg-white p-4">
        <ToggleGroup
          label="Panel"
          value={panel}
          onChange={setPanel}
          options={[
            { id: "rank", label: "Share ranking" },
            { id: "change", label: "Share change" },
            { id: "providers", label: "Providers" },
            { id: "scatter", label: "Share ?? units" },
          ]}
        />
        <ToggleGroup
          label="Size band"
          value={band}
          onChange={setBand}
          options={[
            { id: "all", label: "All" },
            { id: "large", label: "???20%" },
            { id: "moderate", label: "10???19%" },
            { id: "small", label: "2???9%" },
            { id: "minimal", label: "<2%" },
          ]}
        />
        <ToggleGroup
          label="Region"
          value={region}
          onChange={setRegion}
          options={[
            { id: "all", label: "All" },
            ...REGIONS.filter((r) => r !== "Latin America").map((r) => ({
              id: r as RegionFilter,
              label: r.replace("Central & Eastern Europe", "CEE").replace("Asia-Pacific", "APAC"),
            })),
          ]}
        />
        <div className="flex flex-wrap items-center gap-4">
          <ToggleGroup
            label="Sort"
            value={sort}
            onChange={setSort}
            options={[
              { id: "share-desc", label: "Share ???" },
              { id: "delta-asc", label: "?? share (shrinking first)" },
              { id: "dwellings-desc", label: "Units ???" },
            ]}
          />
          <label className="inline-flex items-center gap-2 text-xs font-medium text-slate-700">
            <input
              type="checkbox"
              checked={materialOnly}
              onChange={(e) => setMaterialOnly(e.target.checked)}
              className="rounded border-slate-300"
            />
            Material stock only (???10%)
          </label>
        </div>
      </div>

      {panel === "rank" ? (
        <ChartCard
          title="Social rental dwellings as % of total housing stock"
          subtitle="2022 or latest available year ?? OECD QuASH. Horizontal bars coloured by size band."
        >
          <div className="h-[520px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={rankData}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis
                  type="number"
                  domain={[0, 40]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="category"
                  dataKey="short"
                  width={110}
                  tick={{ fontSize: 11, fill: NAVY }}
                />
                <Tooltip
                  formatter={(value) => [fmtPct(Number(value)), "Share"]}
                  labelFormatter={(l) => String(l)}
                />
                <ReferenceLine
                  x={AGGREGATES[0].sharePct}
                  stroke={ROSE}
                  strokeDasharray="4 4"
                  label={{ value: "OECD", fill: ROSE, fontSize: 10, position: "top" }}
                />
                <Bar dataKey="sharePct" name="Share of stock" radius={[0, 4, 4, 0]}>
                  {rankData.map((r) => (
                    <Cell key={r.id} fill={BAND_COLOR[r.sizeBand]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <LegendStrip />
        </ChartCard>
      ) : null}

      {panel === "change" ? (
        <ChartCard
          title="Share change: ~2010 ??? latest"
          subtitle={`${shrinkCount} shrinking ?? ${growCount} growing in the filtered set. Dumbbells show paired OECD observations.`}
        >
          <div className="h-[520px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={changeData}
                layout="vertical"
                margin={{ top: 8, right: 28, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis
                  type="number"
                  domain={[0, 42]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="category"
                  dataKey="short"
                  width={110}
                  tick={{ fontSize: 11, fill: NAVY }}
                />
                <Tooltip
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0]?.payload as (typeof changeData)[0];
                    return (
                      <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs shadow-md">
                        <p className="font-semibold text-slate-900">{d.country}</p>
                        <p className="text-slate-600">
                          ~{d.year2010}: {fmtPct(d.around2010 ?? 0)} ??? {d.yearLatest}:{" "}
                          {fmtPct(d.latest ?? 0)}
                        </p>
                        <p className={d.delta != null && d.delta < 0 ? "text-rose-700" : "text-teal-700"}>
                          {fmtPp(d.delta ?? 0)}
                        </p>
                        <p className="text-slate-500">
                          Units: {fmtDwellings(d.dwellings2010)} ??? {fmtDwellings(d.dwellingsLatest)}
                        </p>
                      </div>
                    );
                  }}
                />
                <ReferenceLine x={0} stroke="#cbd5e1" />
                <Line
                  dataKey="around2010"
                  name="~2010"
                  stroke={SLATE}
                  strokeWidth={0}
                  dot={{ r: 5, fill: SLATE, strokeWidth: 0 }}
                  isAnimationActive={false}
                />
                <Line
                  dataKey="latest"
                  name="Latest"
                  stroke={TEAL}
                  strokeWidth={0}
                  dot={{ r: 5, fill: TEAL, strokeWidth: 0 }}
                  isAnimationActive={false}
                />
                <Bar dataKey="delta" name="?? pp (axis unused)" hide />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-3 grid gap-2 sm:grid-cols-2">
            {changeData.slice(0, 8).map((d) => (
              <div
                key={d.id}
                className="flex items-center justify-between rounded-lg border border-slate-100 bg-slate-50 px-3 py-2 text-xs"
              >
                <span className="font-medium text-slate-800">{d.short}</span>
                <span
                  className={
                    (d.delta ?? 0) < 0 ? "font-semibold text-rose-700" : "font-semibold text-teal-700"
                  }
                >
                  {fmtPp(d.delta ?? 0)}
                </span>
              </div>
            ))}
          </div>
        </ChartCard>
      ) : null}

      {panel === "providers" ? (
        <ChartCard
          title="Who owns the social rental stock?"
          subtitle="Share of social rental dwellings by provider type (latest QuASH). Germany shown as other (L??nder-level mix not disclosed in PH4.2.2)."
        >
          <div className="h-[420px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={providerData}
                layout="vertical"
                margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                stackOffset="expand"
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis
                  type="number"
                  tickFormatter={(v) => `${Math.round(v * 100)}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="category"
                  dataKey="short"
                  width={110}
                  tick={{ fontSize: 11, fill: NAVY }}
                />
                <Tooltip
                  formatter={(v: number) => [`${v.toFixed(1)}%`, ""]}
                />
                <Legend wrapperStyle={{ fontSize: 12 }} />
                <Bar dataKey="national" stackId="p" name="National / public agency" fill={NAVY} />
                <Bar dataKey="municipal" stackId="p" name="Regional / municipal" fill={SKY} />
                <Bar dataKey="nonprofit" stackId="p" name="Nonprofit / coop" fill={TEAL} />
                <Bar dataKey="forProfit" stackId="p" name="For-profit" fill={AMBER} />
                <Bar dataKey="other" stackId="p" name="Other" fill={VIOLET} radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "scatter" ? (
        <ChartCard
          title="Share of stock vs absolute social rental units"
          subtitle="Bubble size scales with unit count. High share ??? largest absolute stock (France and the US hold millions of units at mid/low shares)."
        >
          <div className="h-[420px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 20, left: 8, bottom: 12 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="x"
                  name="Share"
                  unit="%"
                  domain={[0, 38]}
                  tick={{ fontSize: 11, fill: SLATE }}
                  label={{ value: "Social rental share of stock (%)", position: "insideBottom", offset: -4, fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Units"
                  tick={{ fontSize: 11, fill: SLATE }}
                  label={{ value: "Social rental dwellings (millions)", angle: -90, position: "insideLeft", offset: 8, fontSize: 11, fill: SLATE }}
                />
                <ZAxis type="number" dataKey="z" range={[40, 280]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0]?.payload as (typeof scatterData)[0];
                    return (
                      <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs shadow-md">
                        <p className="font-semibold text-slate-900">{d.country}</p>
                        <p>{fmtPct(d.sharePct)} of stock ?? {fmtDwellings(d.dwellings)} units</p>
                        <p className="text-slate-500">{SIZE_BAND_LABELS[d.sizeBand]} ?? {d.year}</p>
                      </div>
                    );
                  }}
                />
                <ReferenceLine
                  x={AGGREGATES[0].sharePct}
                  stroke={ROSE}
                  strokeDasharray="4 4"
                />
                <Scatter data={scatterData} name="Countries">
                  {scatterData.map((r) => (
                    <Cell key={r.id} fill={BAND_COLOR[r.sizeBand]} fillOpacity={0.85} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <LegendStrip />
        </ChartCard>
      ) : null}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-lg border border-slate-200 bg-white px-3 py-2">
      <p className="text-[10px] font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </p>
      <p className="mt-0.5 text-sm font-bold text-slate-900">{value}</p>
    </div>
  );
}

function LegendStrip() {
  return (
    <div className="mt-3 flex flex-wrap gap-3 text-xs text-slate-600">
      {(Object.keys(BAND_COLOR) as SizeBand[]).map((b) => (
        <span key={b} className="inline-flex items-center gap-1.5">
          <span
            className="inline-block h-2.5 w-2.5 rounded-sm"
            style={{ background: BAND_COLOR[b] }}
          />
          {SIZE_BAND_LABELS[b]}
        </span>
      ))}
      <span className="inline-flex items-center gap-1.5 text-rose-700">
        <span className="inline-block h-px w-4 border-t border-dashed border-rose-600" />
        OECD average
      </span>
    </div>
  );
}

success.beforeFullFileContent:
"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AGGREGATES,
  COUNTRY_STOCK,
  HEADLINE,
  PROVIDER_MIX,
  REGIONS,
  SIZE_BAND_LABELS,
  SOURCE_NOTE,
  TRENDS,
  fmtDwellings,
  fmtPct,
  fmtPp,
  type Region,
  type SizeBand,
} from "@/data/social-housing-stock-share-in-oecd-2026-data";

// viz-types: ranked bars, slope/dumbbell deltas, provider stacked bars, share??units scatter | layout: default

type PanelId = "rank" | "change" | "providers" | "scatter";
type BandFilter = "all" | SizeBand;
type RegionFilter = "all" | Region;
type SortMode = "share-desc" | "delta-asc" | "dwellings-desc";

const NAVY = "#0f172a";
const TEAL = "#0f766e";
const AMBER = "#d97706";
const ROSE = "#be123c";
const SLATE = "#64748b";
const SKY = "#0284c7";
const LIME = "#65a30d";
const VIOLET = "#7c3aed";

const BAND_COLOR: Record<SizeBand, string> = {
  large: TEAL,
  moderate: SKY,
  small: AMBER,
  minimal: SLATE,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((opt) => {
          const active = opt.id === value;
          return (
            <button
              key={opt.id}
              type="button"
              onClick={() => onChange(opt.id)}
              className={`rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
                active
                  ? "bg-slate-900 text-white"
                  : "text-slate-600 hover:bg-slate-100"
              }`}
            >
              {opt.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

export function SocialHousingStockShareInOecd2026Dashboard() {
  const [panel, setPanel] = useState<PanelId>("rank");
  const [band, setBand] = useState<BandFilter>("all");
  const [region, setRegion] = useState<RegionFilter>("all");
  const [sort, setSort] = useState<SortMode>("share-desc");
  const [materialOnly, setMaterialOnly] = useState(false);

  const filteredStock = useMemo(() => {
    let rows = COUNTRY_STOCK.filter((r) => r.id !== "col" || !materialOnly);
    if (materialOnly) rows = rows.filter((r) => r.sharePct >= 10);
    if (band !== "all") rows = rows.filter((r) => r.sizeBand === band);
    if (region !== "all") rows = rows.filter((r) => r.region === region);
    return rows;
  }, [band, region, materialOnly]);

  const rankData = useMemo(() => {
    const rows = [...filteredStock];
    if (sort === "dwellings-desc") {
      rows.sort((a, b) => (b.dwellings ?? 0) - (a.dwellings ?? 0));
    } else {
      rows.sort((a, b) => b.sharePct - a.sharePct);
    }
    return rows.map((r) => ({
      ...r,
      short: r.country.replace("United Kingdom (England)", "UK (Eng.)"),
    }));
  }, [filteredStock, sort]);

  const changeData = useMemo(() => {
    let rows = TRENDS.filter((t) => t.deltaPp != null);
    if (materialOnly) rows = rows.filter((t) => (t.shareLatest ?? 0) >= 10);
    if (region !== "all") rows = rows.filter((t) => t.region === region);
    if (band !== "all") {
      rows = rows.filter((t) => {
        const stock = COUNTRY_STOCK.find((c) => c.id === t.id);
        return stock?.sizeBand === band;
      });
    }
    rows = [...rows].sort((a, b) =>
      sort === "delta-asc"
        ? (a.deltaPp ?? 0) - (b.deltaPp ?? 0)
        : (b.shareLatest ?? 0) - (a.shareLatest ?? 0),
    );
    return rows.map((t) => ({
      ...t,
      short: t.country.replace("United Kingdom (England)", "UK (Eng.)"),
      around2010: t.shareAround2010,
      latest: t.shareLatest,
      delta: t.deltaPp,
    }));
  }, [band, region, materialOnly, sort]);

  const providerData = useMemo(() => {
    let rows = [...PROVIDER_MIX];
    if (region !== "all") {
      const ids = new Set(
        COUNTRY_STOCK.filter((c) => c.region === region).map((c) => c.id),
      );
      rows = rows.filter((r) => ids.has(r.id));
    }
    if (materialOnly) {
      const ids = new Set(
        COUNTRY_STOCK.filter((c) => c.sharePct >= 10).map((c) => c.id),
      );
      rows = rows.filter((r) => ids.has(r.id));
    }
    return rows.map((r) => ({
      short: r.country.replace("United Kingdom (England)", "UK (Eng.)"),
      national: +(r.nationalPct * 100).toFixed(1),
      municipal: +(r.regionalMunicipalPct * 100).toFixed(1),
      nonprofit: +(r.nonprofitCoopPct * 100).toFixed(1),
      forProfit: +(r.forProfitPct * 100).toFixed(1),
      other: +(r.otherPct * 100).toFixed(1),
    }));
  }, [region, materialOnly]);

  const scatterData = useMemo(() => {
    return filteredStock
      .filter((r) => r.dwellings != null && r.dwellings > 0)
      .map((r) => ({
        ...r,
        x: r.sharePct,
        y: (r.dwellings ?? 0) / 1_000_000,
        z: Math.max(40, Math.sqrt(r.dwellings ?? 0) / 25),
        short: r.country.replace("United Kingdom (England)", "UK (Eng.)"),
      }));
  }, [filteredStock]);

  const shrinkCount = changeData.filter((d) => (d.delta ?? 0) < 0).length;
  const growCount = changeData.filter((d) => (d.delta ?? 0) > 0).length;

  return (
    <div className="space-y-6" data-viz="social-housing-stock-share-in-oecd-2026">
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-50 to-white p-5 sm:p-6">
        <p className="text-xs font-semibold uppercase tracking-wide text-teal-800">
          Social rental % of dwellings ?? OECD PH4.2
        </p>
        <h2 className="mt-1 text-xl font-bold text-slate-900 sm:text-2xl">
          Social rental stock: who still has scale, and who is losing share
        </h2>
        <p className="mt-2 max-w-3xl text-sm leading-relaxed text-slate-600">
          Across the OECD, social rental dwellings average{" "}
          <span className="font-semibold text-slate-900">
            {fmtPct(HEADLINE.oecdAvgSharePct)}
          </span>{" "}
          of the housing stock (~{HEADLINE.socialDwellingsMillionApprox}M units).
          Only {HEADLINE.countriesAbove20} countries still clear 20%;{" "}
          {HEADLINE.countriesAbove10} clear 10%. Most paired histories show share
          erosion even when absolute unit counts rise.
        </p>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
          <Stat label="OECD avg share" value={fmtPct(HEADLINE.oecdAvgSharePct)} />
          <Stat label="Largest share" value={`${HEADLINE.largestShareCountry} ${fmtPct(HEADLINE.largestSharePct)}`} />
          <Stat label="Steepest share drop" value={`${HEADLINE.steepestDropCountry} ${fmtPp(HEADLINE.steepestDropPp)}`} />
          <Stat label="Material (???10%)" value={`${HEADLINE.countriesAbove10} countries`} />
        </div>
      </div>

      <div className="flex flex-col gap-3 rounded-xl border border-slate-200 bg-white p-4">
        <ToggleGroup
          label="Panel"
          value={panel}
          onChange={setPanel}
          options={[
            { id: "rank", label: "Share ranking" },
            { id: "change", label: "Share change" },
            { id: "providers", label: "Providers" },
            { id: "scatter", label: "Share ?? units" },
          ]}
        />
        <ToggleGroup
          label="Size band"
          value={band}
          onChange={setBand}
          options={[
            { id: "all", label: "All" },
            { id: "large", label: "???20%" },
            { id: "moderate", label: "10???19%" },
            { id: "small", label: "2???9%" },
            { id: "minimal", label: "<2%" },
          ]}
        />
        <ToggleGroup
          label="Region"
          value={region}
          onChange={setRegion}
          options={[
            { id: "all", label: "All" },
            ...REGIONS.filter((r) => r !== "Latin America").map((r) => ({
              id: r as RegionFilter,
              label: r.replace("Central & Eastern Europe", "CEE").replace("Asia-Pacific", "APAC"),
            })),
          ]}
        />
        <div className="flex flex-wrap items-center gap-4">
          <ToggleGroup
            label="Sort"
            value={sort}
            onChange={setSort}
            options={[
              { id: "share-desc", label: "Share ???" },
              { id: "delta-asc", label: "?? share (shrinking first)" },
              { id: "dwellings-desc", label: "Units ???" },
            ]}
          />
          <label className="inline-flex items-center gap-2 text-xs font-medium text-slate-700">
            <input
              type="checkbox"
              checked={materialOnly}
              onChange={(e) => setMaterialOnly(e.target.checked)}
              className="rounded border-slate-300"
            />
            Material stock only (???10%)
          </label>
        </div>
      </div>

      {panel === "rank" ? (
        <ChartCard
          title="Social rental dwellings as % of total housing stock"
          subtitle="2022 or latest available year ?? OECD QuASH. Horizontal bars coloured by size band."
        >
          <div className="h-[520px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={rankData}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis
                  type="number"
                  domain={[0, 40]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="category"
                  dataKey="short"
                  width={110}
                  tick={{ fontSize: 11, fill: NAVY }}
                />
                <Tooltip
                  formatter={(value) => [fmtPct(Number(value)), "Share"]}
                  labelFormatter={(l) => String(l)}
                />
                <ReferenceLine
                  x={AGGREGATES[0].sharePct}
                  stroke={ROSE}
                  strokeDasharray="4 4"
                  label={{ value: "OECD", fill: ROSE, fontSize: 10, position: "top" }}
                />
                <Bar dataKey="sharePct" name="Share of stock" radius={[0, 4, 4, 0]}>
                  {rankData.map((r) => (
                    <Cell key={r.id} fill={BAND_COLOR[r.sizeBand]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <LegendStrip />
        </ChartCard>
      ) : null}

      {panel === "change" ? (
        <ChartCard
          title="Share change: ~2010 ??? latest"
          subtitle={`${shrinkCount} shrinking ?? ${growCount} growing in the filtered set. Dumbbells show paired OECD observations.`}
        >
          <div className="h-[520px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={changeData}
                layout="vertical"
                margin={{ top: 8, right: 28, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis
                  type="number"
                  domain={[0, 42]}
                  tickFormatter={(v) => `${v}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="category"
                  dataKey="short"
                  width={110}
                  tick={{ fontSize: 11, fill: NAVY }}
                />
                <Tooltip
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0]?.payload as (typeof changeData)[0];
                    return (
                      <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs shadow-md">
                        <p className="font-semibold text-slate-900">{d.country}</p>
                        <p className="text-slate-600">
                          ~{d.year2010}: {fmtPct(d.around2010 ?? 0)} ??? {d.yearLatest}:{" "}
                          {fmtPct(d.latest ?? 0)}
                        </p>
                        <p className={d.delta != null && d.delta < 0 ? "text-rose-700" : "text-teal-700"}>
                          {fmtPp(d.delta ?? 0)}
                        </p>
                        <p className="text-slate-500">
                          Units: {fmtDwellings(d.dwellings2010)} ??? {fmtDwellings(d.dwellingsLatest)}
                        </p>
                      </div>
                    );
                  }}
                />
                <ReferenceLine x={0} stroke="#cbd5e1" />
                <Line
                  dataKey="around2010"
                  name="~2010"
                  stroke={SLATE}
                  strokeWidth={0}
                  dot={{ r: 5, fill: SLATE, strokeWidth: 0 }}
                  isAnimationActive={false}
                />
                <Line
                  dataKey="latest"
                  name="Latest"
                  stroke={TEAL}
                  strokeWidth={0}
                  dot={{ r: 5, fill: TEAL, strokeWidth: 0 }}
                  isAnimationActive={false}
                />
                <Bar dataKey="delta" name="?? pp (axis unused)" hide />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-3 grid gap-2 sm:grid-cols-2">
            {changeData.slice(0, 8).map((d) => (
              <div
                key={d.id}
                className="flex items-center justify-between rounded-lg border border-slate-100 bg-slate-50 px-3 py-2 text-xs"
              >
                <span className="font-medium text-slate-800">{d.short}</span>
                <span
                  className={
                    (d.delta ?? 0) < 0 ? "font-semibold text-rose-700" : "font-semibold text-teal-700"
                  }
                >
                  {fmtPp(d.delta ?? 0)}
                </span>
              </div>
            ))}
          </div>
        </ChartCard>
      ) : null}

      {panel === "providers" ? (
        <ChartCard
          title="Who owns the social rental stock?"
          subtitle="Share of social rental dwellings by provider type (latest QuASH). Germany shown as other (L??nder-level mix not disclosed in PH4.2.2)."
        >
          <div className="h-[420px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={providerData}
                layout="vertical"
                margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                stackOffset="expand"
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis
                  type="number"
                  tickFormatter={(v) => `${Math.round(v * 100)}%`}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="category"
                  dataKey="short"
                  width={110}
                  tick={{ fontSize: 11, fill: NAVY }}
                />
                <Tooltip
                  formatter={(v: number) => [`${v.toFixed(1)}%`, ""]}
                />
                <Legend wrapperStyle={{ fontSize: 12 }} />
                <Bar dataKey="national" stackId="p" name="National / public agency" fill={NAVY} />
                <Bar dataKey="municipal" stackId="p" name="Regional / municipal" fill={SKY} />
                <Bar dataKey="nonprofit" stackId="p" name="Nonprofit / coop" fill={TEAL} />
                <Bar dataKey="forProfit" stackId="p" name="For-profit" fill={AMBER} />
                <Bar dataKey="other" stackId="p" name="Other" fill={VIOLET} radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "scatter" ? (
        <ChartCard
          title="Share of stock vs absolute social rental units"
          subtitle="Bubble size scales with unit count. High share ??? largest absolute stock (France and the US hold millions of units at mid/low shares)."
        >
          <div className="h-[420px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 20, left: 8, bottom: 12 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="x"
                  name="Share"
                  unit="%"
                  domain={[0, 38]}
                  tick={{ fontSize: 11, fill: SLATE }}
                  label={{ value: "Social rental share of stock (%)", position: "insideBottom", offset: -4, fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="number"
                  dataKey="y"
                  name="Units"
                  tick={{ fontSize: 11, fill: SLATE }}
                  label={{ value: "Social rental dwellings (millions)", angle: -90, position: "insideLeft", offset: 8, fontSize: 11, fill: SLATE }}
                />
                <ZAxis type="number" dataKey="z" range={[40, 280]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  content={({ active, payload }) => {
                    if (!active || !payload?.length) return null;
                    const d = payload[0]?.payload as (typeof scatterData)[0];
                    return (
                      <div className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs shadow-md">
                        <p className="font-semibold text-slate-900">{d.country}</p>
                        <p>{fmtPct(d.sharePct)} of stock ?? {fmtDwellings(d.dwellings)} units</p>
                        <p className="text-slate-500">{SIZE_BAND_LABELS[d.sizeBand]} ?? {d.year}</p>
                      </div>
                    );
                  }}
                />
                <ReferenceLine
                  x={AGGREGATES[0].sharePct}
                  stroke={ROSE}
                  strokeDasharray="4 4"
                />
                <Scatter data={scatterData} name="Countries">
                  {scatterData.map((r) => (
                    <Cell key={r.id} fill={BAND_COLOR[r.sizeBand]} fillOpacity={0.85} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <LegendStrip />
        </ChartCard>
      ) : null}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-lg border border-slate-200 bg-white px-3 py-2">
      <p className="text-[10px] font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </p>
      <p className="mt-0.5 text-sm font-bold text-slate-900">{value}</p>
    </div>
  );
}

function LegendStrip() {
  return (
    <div className="mt-3 flex flex-wrap gap-3 text-xs text-slate-600">
      {(Object.keys(BAND_COLOR) as SizeBand[]).map((b) => (
        <span key={b} className="inline-flex items-center gap-1.5">
          <span
            className="inline-block h-2.5 w-2.5 rounded-sm"
            style={{ background: BAND_COLOR[b] }}
          />
          {SIZE_BAND_LABELS[b]}
        </span>
      ))}
      <span className="inline-flex items-center gap-1.5 text-rose-700">
        <span className="inline-block h-px w-4 border-t border-dashed border-rose-600" />
        OECD average
      </span>
    </div>
  );
}

